use std::arch::asm;
#[inline(never)]unsafe fn paired(x:*mut u64,y:*mut u64,mut reps:usize){unsafe{asm!("2:","ldp q0, q1, [{x}]","ldp q2, q3, [{y}]","stp q0, q1, [{y}]","stp q2, q3, [{x}]","subs {r}, {r}, #1","b.ne 2b",x=in(reg)x,y=in(reg)y,r=inout(reg)reps=>_,out("v0")_,out("v1")_,out("v2")_,out("v3")_,options(nostack));}}
#[inline(never)]unsafe fn singles(x:*mut u64,y:*mut u64,mut reps:usize){unsafe{asm!("2:","ldr q0, [{x}]","ldr q1, [{x}, #16]","ldr q2, [{y}]","ldr q3, [{y}, #16]","str q0, [{y}]","str q1, [{y}, #16]","str q2, [{x}]","str q3, [{x}, #16]","subs {r}, {r}, #1","b.ne 2b",x=in(reg)x,y=in(reg)y,r=inout(reg)reps=>_,out("v0")_,out("v1")_,out("v2")_,out("v3")_,options(nostack));}}
#[inline(never)]unsafe fn pair_split(x:*mut u64,y:*mut u64,mut reps:usize){unsafe{asm!("2:","ldp q0, q1, [{x}]","ldp q2, q3, [{y}]","umov x9, v1.d[0]","umov x10, v1.d[1]","umov x11, v3.d[0]","umov x12, v3.d[1]","str q0, [{y}]","str x9, [{y}, #16]","str x10, [{y}, #24]","str q2, [{x}]","str x11, [{x}, #16]","str x12, [{x}, #24]","subs {r}, {r}, #1","b.ne 2b",x=in(reg)x,y=in(reg)y,r=inout(reg)reps=>_,out("v0")_,out("v1")_,out("v2")_,out("v3")_,out("x9")_,out("x10")_,out("x11")_,out("x12")_,options(nostack));}}
#[inline(never)]unsafe fn single_split(x:*mut u64,y:*mut u64,mut reps:usize){unsafe{asm!("2:","ldr q0, [{x}]","ldr q1, [{x}, #16]","ldr q2, [{y}]","ldr q3, [{y}, #16]","umov x9, v1.d[0]","umov x10, v1.d[1]","umov x11, v3.d[0]","umov x12, v3.d[1]","str q0, [{y}]","str x9, [{y}, #16]","str x10, [{y}, #24]","str q2, [{x}]","str x11, [{x}, #16]","str x12, [{x}, #24]","subs {r}, {r}, #1","b.ne 2b",x=in(reg)x,y=in(reg)y,r=inout(reg)reps=>_,out("v0")_,out("v1")_,out("v2")_,out("v3")_,out("x9")_,out("x10")_,out("x11")_,out("x12")_,options(nostack));}}
fn main(){let a:Vec<_>=std::env::args().collect();let mode=&a[1];let reps:usize=a[2].parse().unwrap();let ax:usize=a[4].parse().unwrap();let ay:usize=a[5].parse().unwrap();let mut data=vec![0u64;128];let base=((64-data.as_ptr()as usize%64)%64)/8;let x=unsafe{data.as_mut_ptr().add(base+ax)};let y=unsafe{data.as_mut_ptr().add(base+64+ay)};for i in 0..4{unsafe{*x.add(i)=i as u64;*y.add(i)=i as u64+100;}}
 let now=std::time::Instant::now();unsafe{match mode.as_str(){"leaf_pair"=>paired(x,y,reps),"leaf_single"=>singles(x,y,reps),"leaf_pair_split"=>pair_split(x,y,reps),"leaf_single_split"=>single_split(x,y,reps),_=>panic!("mode")}}let elapsed=now.elapsed().as_nanos();for i in 0..4{unsafe{assert_eq!(*x.add(i),i as u64+if reps%2==1{100}else{0});assert_eq!(*y.add(i),i as u64+if reps%2==1{0}else{100});}}println!("{{\"elapsed_ns\":{},\"reps\":{},\"x_mod64\":{},\"y_mod64\":{}}}",elapsed,reps,x as usize%64,y as usize%64);}
